final class RecipeSync {
 static final String BASE="https://psipfadpuciwjdyiuxqj.supabase.co",ENDPOINT=BASE+"/functions/v1/receitas-onca-sync",SEED="00000000-0000-4000-8000-000000000001";
 final MainActivity app;final SQLiteDatabase db;volatile boolean busy=false;String token,status="Conectar livro para sincronizar";int conflicts;TextView statusView;final Handler handler=new Handler(Looper.getMainLooper());final String[] fields={"name","category","origin","time","yield","ingredients","steps","notes"};
 final Runnable ticker=new Runnable(){public void run(){sync(false);handler.postDelayed(this,30000);}};
 RecipeSync(MainActivity a){app=a;db=a.db;token=TokenVault.get(a);if(!token.isEmpty())status="Livro conectado · toque para sincronizar";}
 static void migrate(SQLiteDatabase db){Set<String> cols=new HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info(recipes)",null)){while(c.moveToNext())cols.add(c.getString(1));}db.beginTransaction();try{for(String def:new String[]{"cloud_id TEXT","cloud_version INTEGER DEFAULT 0","sync_dirty INTEGER DEFAULT 1","deleted INTEGER DEFAULT 0","edit_seq INTEGER DEFAULT 0"})if(!cols.contains(def.split(" ")[0]))db.execSQL("ALTER TABLE recipes ADD COLUMN "+def);db.execSQL("CREATE UNIQUE INDEX IF NOT EXISTS recipes_cloud_id ON recipes(cloud_id)");db.execSQL("CREATE TABLE IF NOT EXISTS sync_media(local_path TEXT PRIMARY KEY,remote_path TEXT NOT NULL)");boolean seeded=false;try(Cursor c=db.rawQuery("SELECT id,name,origin FROM recipes WHERE cloud_id IS NULL",null)){while(c.moveToNext()){boolean seed=!seeded&&"Bolo de fubá".equals(c.getString(1))&&"carmela".equals(c.getString(2));ContentValues v=new ContentValues();v.put("cloud_id",seed?SEED:UUID.randomUUID().toString());seeded|=seed;db.update("recipes",v,"id=?",new String[]{c.getString(0)});}}db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void start(){handler.removeCallbacks(ticker);handler.post(ticker);}void stop(){handler.removeCallbacks(ticker);}
 void ui(Runnable r){app.runOnUiThread(()->{if(!app.isDestroyed()&&!app.isFinishing())r.run();});}
 void bind(TextView t){statusView=t;t.setText(status);t.setOnClickListener(v->{if(token.isEmpty())join();else sync(true);});}
 void status(String s){status=s;ui(()->{if(statusView!=null)statusView.setText(s);});}
 void join(){if(busy)return;EditText input=new EditText(app);input.setHint("ONCA-…");input.setSingleLine();input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);input.setPadding(app.d(20),app.d(15),app.d(20),app.d(15));AlertDialog d=new AlertDialog.Builder(app).setTitle("Conectar o livro").setMessage("Cole o mesmo código em todos os celulares. Quem tiver o código verá e poderá editar as receitas e fotos compartilhadas. As exclusões também serão sincronizadas.").setView(input).setNegativeButton("Depois",null).setPositiveButton("Conectar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String code=input.getText().toString().trim().toUpperCase(Locale.ROOT);if(!code.matches("ONCA-[0-9A-F]{16}")){input.setError("Cole o código completo.");return;}busy=true;d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject b=new JSONObject();b.put("code",code);b.put("name",Build.MANUFACTURER+" "+Build.MODEL);JSONObject result=request("join","POST",b);String t=result.getString("token");TokenVault.save(app,t);token=t;ui(d::dismiss);}catch(Exception e){ui(()->{input.setError(e.getMessage());d.getButton(-1).setEnabled(true);});}finally{busy=false;if(!token.isEmpty())sync(false);}}).start();}));d.show();}
 static class SyncError extends IOException{final int code;SyncError(int c,String m){super(m);code=c;}}
 JSONObject request(String action,String method,JSONObject body)throws Exception{return new JSONObject(send(ENDPOINT+"?action="+action,method,body==null?null:body.toString().getBytes(StandardCharsets.UTF_8),"application/json"));}
 String send(String target,String method,byte[] bytes,String type)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(target).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(40000);c.setRequestMethod(method);c.setRequestProperty("Content-Type",type);if(!token.isEmpty())c.setRequestProperty("x-onca-session",token);try{if(bytes!=null){c.setDoOutput(true);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}}int code=c.getResponseCode();String result=read(code<400?c.getInputStream():c.getErrorStream(),8*1024*1024);if(code>=400){String message="Não foi possível conectar agora.";try{message=new JSONObject(result).optString("error",message);}catch(Exception ignored){}throw new SyncError(code,message);}return result;}finally{c.disconnect();}}
 String read(InputStream stream,int max)throws Exception{if(stream==null)return "";try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Resposta muito grande.");out.write(b,0,n);}return out.toString("UTF-8");}}
 long num(ContentValues v,String k){Long n=v.getAsLong(k);return n==null?0:n;}
 List<ContentValues> rows(String where,String[] args){List<ContentValues> result=new ArrayList<>();try(Cursor c=db.query("recipes",null,where,args,null,null,"id")){while(c.moveToNext()){ContentValues r=new ContentValues();for(String k:c.getColumnNames()){int i=c.getColumnIndexOrThrow(k);if(c.isNull(i))r.putNull(k);else if(c.getType(i)==Cursor.FIELD_TYPE_INTEGER)r.put(k,c.getLong(i));else r.put(k,c.getString(i));}result.add(r);}}return result;}
 void sync(boolean manual){if(token.isEmpty()){if(manual)join();return;}if(busy||app.editingScreen)return;busy=true;conflicts=0;status("Sincronizando receitas e fotos…");new Thread(()->{try{pull();for(ContentValues local:rows("sync_dirty=1",null)){if(app.editingScreen)break;push(local);}pull();status(rows("sync_dirty=1",null).isEmpty()?"Livro sincronizado · toque para atualizar":"Alterações pendentes · toque para enviar");ui(()->{if(!app.editingScreen&&app.list!=null&&app.list.getParent()==app.body)app.render();if(conflicts>0)Toast.makeText(app,"Edição simultânea preservada como cópia. Confira o livro.",Toast.LENGTH_LONG).show();});}catch(SyncError e){if(e.code==401){token="";app.getSharedPreferences("onca-sync",0).edit().remove("session").apply();status("Conecte novamente o livro");}else status("Não sincronizado · toque para tentar");if(manual)ui(()->Toast.makeText(app,e.getMessage(),Toast.LENGTH_LONG).show());}catch(Exception e){status("Sem sincronização · receitas salvas no celular");if(manual)ui(()->Toast.makeText(app,"Não foi possível sincronizar agora. Tente com internet.",Toast.LENGTH_LONG).show());}finally{busy=false;}}).start();}
 void push(ContentValues local)throws Exception{JSONObject body=new JSONObject();for(String k:fields)body.put(k,app.val(local,k));boolean deleted=num(local,"deleted")==1;body.put("photo",deleted?"":upload(app.val(local,"photo")));JSONArray photos=app.parsePhotos(app.val(local,"step_photos")),remote=new JSONArray();for(int i=0;i<photos.length();i++)remote.put(deleted?"":upload(photos.optString(i,"")));body.put("step_photos",remote);body.put("favorite",num(local,"favorite"));JSONObject envelope=new JSONObject();envelope.put("id",app.val(local,"cloud_id"));envelope.put("version",num(local,"cloud_version"));envelope.put("body",body);envelope.put("deleted",deleted);JSONObject response;try{response=request("recipes","PUT",envelope);}catch(SyncError e){if(e.code==409)return;throw e;}synchronized(db){ContentValues v=new ContentValues();v.put("cloud_version",response.getLong("version"));db.update("recipes",v,"id=?",new String[]{app.val(local,"id")});v.clear();v.put("sync_dirty",0);db.update("recipes",v,"id=? AND edit_seq=?",new String[]{app.val(local,"id"),app.val(local,"edit_seq")});}}
 String upload(String path)throws Exception{if(path.isEmpty())return "";try(Cursor c=db.rawQuery("SELECT remote_path FROM sync_media WHERE local_path=?",new String[]{path})){if(c.moveToFirst())return c.getString(0);}BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(path,o);if(o.outWidth<=0||o.outHeight<=0)throw new IOException("Foto não encontrada.");o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1800||o.outHeight/o.inSampleSize>1800)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeFile(path,o);if(image==null)throw new IOException("Foto inválida.");byte[] bytes;try(ByteArrayOutputStream out=new ByteArrayOutputStream()){image.compress(Bitmap.CompressFormat.JPEG,82,out);bytes=out.toByteArray();}finally{image.recycle();}String remote=new JSONObject(send(ENDPOINT+"?action=media","POST",bytes,"image/jpeg")).getString("path");ContentValues v=new ContentValues();v.put("local_path",path);v.put("remote_path",remote);db.insertWithOnConflict("sync_media",null,v,SQLiteDatabase.CONFLICT_REPLACE);return remote;}
 String download(String path,String url)throws Exception{if(path.isEmpty())return "";try(Cursor c=db.rawQuery("SELECT local_path FROM sync_media WHERE remote_path=?",new String[]{path})){while(c.moveToNext()){File f=new File(c.getString(0));if(f.exists()&&f.length()>0)return f.getAbsolutePath();}}URL target=new URL(url);if(!"https".equals(target.getProtocol())||!"psipfadpuciwjdyiuxqj.supabase.co".equals(target.getHost()))throw new IOException("Foto inválida.");File dir=new File(app.getFilesDir(),"cloud-images");dir.mkdirs();File f=new File(dir,UUID.randomUUID()+".jpg");HttpURLConnection c=(HttpURLConnection)target.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(40000);try{if(c.getResponseCode()!=200)throw new IOException("Foto indisponível.");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(f)){byte[] b=new byte[65536];int n;long size=0;while((n=in.read(b))!=-1){size+=n;if(size>8388608)throw new IOException("Foto muito grande.");out.write(b,0,n);}}ContentValues v=new ContentValues();v.put("local_path",f.getAbsolutePath());v.put("remote_path",path);db.insertWithOnConflict("sync_media",null,v,SQLiteDatabase.CONFLICT_REPLACE);return f.getAbsolutePath();}catch(Exception e){f.delete();throw e;}finally{c.disconnect();}}
 void pull()throws Exception{int offset=0;boolean more;do{JSONObject response=request("recipes&offset="+offset,"GET",null);JSONArray remote=response.getJSONArray("recipes");for(int i=0;i<remote.length();i++){if(app.editingScreen)return;apply(remote.getJSONObject(i));}more=response.getBoolean("more");offset+=remote.length();}while(more);}
 void apply(JSONObject row)throws Exception{String id=row.getString("id");long version=row.getLong("version");List<ContentValues> found=rows("cloud_id=?",new String[]{id});ContentValues local=found.isEmpty()?null:found.get(0);if(local!=null&&num(local,"cloud_version")>=version)return;boolean conflict=local!=null&&num(local,"sync_dirty")==1&&!(SEED.equals(id)&&num(local,"cloud_version")==0&&num(local,"edit_seq")==0);if(conflict&&num(local,"cloud_version")==0&&!SEED.equals(id))return;
 JSONObject body=row.getJSONObject("body");boolean deleted=row.getBoolean("deleted");ContentValues value=new ContentValues();for(String k:fields)value.put(k,body.optString(k,""));value.put("photo",deleted?"":download(body.optString("photo",""),row.optString("photoUrl","")));JSONArray photos=body.optJSONArray("step_photos"),urls=row.optJSONArray("stepUrls"),paths=new JSONArray();if(!deleted&&photos!=null)for(int i=0;i<photos.length();i++)paths.put(download(photos.optString(i,""),urls==null?"":urls.optString(i,"")));value.put("step_photos",paths.toString());value.put("video",local==null?"":app.val(local,"video"));value.put("favorite",body.optInt("favorite",0));value.put("cloud_id",id);value.put("cloud_version",version);value.put("sync_dirty",0);value.put("deleted",deleted?1:0);value.put("edit_seq",local==null?0:num(local,"edit_seq"));
 synchronized(db){if(app.editingScreen)return;db.beginTransaction();try{if(local==null){if(!rows("cloud_id=?",new String[]{id}).isEmpty())return;db.insertOrThrow("recipes",null,value);}else{List<ContentValues> current=rows("id=?",new String[]{app.val(local,"id")});if(current.isEmpty()||num(current.get(0),"edit_seq")!=num(local,"edit_seq"))return;if(conflict){if(num(local,"deleted")==0){ContentValues copy=new ContentValues(local);copy.remove("id");copy.put("cloud_id",UUID.randomUUID().toString());copy.put("cloud_version",0);copy.put("sync_dirty",1);copy.put("edit_seq",0);copy.put("name",app.val(local,"name")+" (cópia da edição)");db.insertOrThrow("recipes",null,copy);}conflicts++;}db.update("recipes",value,"id=?",new String[]{app.val(local,"id")});}db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 void changed(long id){synchronized(db){db.execSQL("UPDATE recipes SET sync_dirty=1,edit_seq=edit_seq+1,cloud_id=coalesce(cloud_id,?) WHERE id=?",new Object[]{UUID.randomUUID().toString(),id});}handler.postDelayed(()->sync(false),300);}
 void delete(long id){synchronized(db){db.execSQL("UPDATE recipes SET deleted=1,sync_dirty=1,edit_seq=edit_seq+1 WHERE id=?",new Object[]{id});}sync(false);}
}
